SyncHttpResponse _titleAndSpaceResponse(
  _Conf config,
  String title,
  String space,
) =>
    SyncHttpClient.get(
      '${config.baseUrl}/content?expand=${Uri.encodeQueryComponent(_contentExpand)}'
      '&title=${Uri.encodeQueryComponent(title)}'
