+  Map<String, dynamic>? findContent(String title, {String? spaceKey});
+
+  /// Raw JSON profile of the user [accountId] (Java `Confluence.profile`);
+  /// `null` (or a throw) when the lookup fails.
+  String? userProfile(String accountId);
